    parents_backward = {goal: None}
    queue_forward = deque([start])
    queue_backward = deque([goal])

    def process_level(queue, parents, opposite_parents):
        for _ in range(len(queue)):
            current = queue.popleft()
            for neighbor in get_neighbors(current):
                if neighbor not in parents:
                    parents[neighbor] = current
                    queue.append(neighbor)
                    if neighbor in opposite_parents:
                        return neighbor
        return None

    while queue_forward and queue_backward:
        meeting = process_level(queue_forward, parents_forward, parents_backward)
        if meeting:
