    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = set()
    heap = [(start[0] + start[1], start[0], start[1], [start])]
    visited.add(start)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        prio, r, c, path = heapq.heappop(heap)
        if (r, c) == goal:
            return path
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                if (nr, nc) == goal:
                    return path + [(nr, nc)]
                visited.add((nr, nc))
                new_prio = nr + nc
                new_path = path + [(nr, nc)]
                heapq.heappush(heap, (new_prio, nr, nc, new_path))
    return []

