def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    sr, sc = start
    gr, gc = goal

    # Check if start or goal are walls
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]

    frontier = [((sr, sc), start)]
    heapq.heapify(frontier)
    came_from = {start: None}

    while frontier:
        _, current = heapq.heappop(frontier)
        if current == goal:
            break
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc) not in came_from:
                    came_from[(nr, nc)] = current
                    heapq.heappush(frontier, ((nr, nc), (nr, nc)))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()
    return path

