        return [start]

    # assign an index to each free cell
    idx = {}
    cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                i = r * cols + c
                idx[(r, c)] = i
                cells.append((r, c))

    n_free = len(cells)

    # build edge list (directed, both directions)
    edges = []
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    for r, c in cells:
        u = idx[(r, c)]
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                v = idx[(nr, nc)]
                edges.append((u, v))

