    heap = [(0, start)]
    came_from = {start: None}
    cost_so_far = {start: 0}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        _, current = heapq.heappop(heap)

        if current == goal:
            break

        cr, cc = current
        for dr, dc in directions:
            nr, nc = cr + dr, cc + dc
